    "function confirmPeriodBlocks() view returns (uint64)",
    "function challengeGracePeriodBlocks() view returns (uint64)"
  ];
  const c = new ethers.Contract(rollup, rollupAbi, provider);
  console.log("Arb One confirmPeriodBlocks:", (await c.confirmPeriodBlocks()).toString());

  // Arb One Sequencer Inbox
  const seqInbox = "0x1c47D875dc03e5218d464660DA6a93A64f8482B6";
  const seqAbi = [
    "function maxTimeVariation() view returns (uint256 delayBlocks, uint256 futureBlocks, uint256 delaySeconds, uint256 futureSeconds)"
  ];
  const cSeq = new ethers.Contract(seqInbox, seqAbi, provider);
  const mtv = await cSeq.maxTimeVariation();
  console.log("Arb One maxTimeVariation:", {
    delayBlocks: mtv.delayBlocks.toString(),
    futureBlocks: mtv.futureBlocks.toString(),
    delaySeconds: mtv.delaySeconds.toString(),
    futureSeconds: mtv.futureSeconds.toString()
  });

  // Sepolia Provider
  const sepoliaRpc = "https://ethereum-sepolia-rpc.publicnode.com";
  const sepoliaProvider = new ethers.JsonRpcProvider(sepoliaRpc);
  const sepRollup = "0xd80810638dbDF9081b72C1B33c65375e807281C8";
  const cSepRollup = new ethers.Contract(sepRollup, rollupAbi, sepoliaProvider);
  console.log("Sepolia confirmPeriodBlocks:", (await cSepRollup.confirmPeriodBlocks()).toString());

  const sepSeqInbox = "0x6c97864CE4bEf387dE0b3310A44230f7E3F1be0D";
  const cSepSeq = new ethers.Contract(sepSeqInbox, seqAbi, sepoliaProvider);
  const sepMtv = await cSepSeq.maxTimeVariation();
  console.log("Sepolia maxTimeVariation:", {
    delayBlocks: sepMtv.delayBlocks.toString(),
    futureBlocks: sepMtv.futureBlocks.toString(),
    delaySeconds: sepMtv.delaySeconds.toString(),
    futureSeconds: sepMtv.futureSeconds.toString()
  });
}
test();
'

